<?php namespace App\Http\Controllers; use App\Models\{Job,Customer,Vehicle,Invoice,Product}; use App\Services\ReportingService; use Illuminate\Support\Facades\DB;
class DashboardController extends Controller {public function __construct(private ReportingService $reporting){} public function index(){ $branch=auth()->user()->branch_id; $metrics=$this->reporting->getDashboardMetrics($branch); $q=fn($m)=>$branch?$m::where('branch_id',$branch):$m::query(); return view('dashboard.index',['vehiclesToday'=>Vehicle::whereHas('customer',fn($q)=>$branch?$q->where('branch_id',$branch):$q)->whereDate('created_at',today())->count(),'activeJobs'=>$metrics['active_jobs'],'completedJobs'=>$metrics['this_month']['completed_jobs'],'revenue'=>$metrics['today']['revenue'],'pendingPayments'=>$metrics['pending_payments'],'lowStock'=>$metrics['low_stock'],'monthlyRevenue'=>$metrics['this_month']['revenue'],'monthlyJobs'=>$metrics['this_month']['jobs']]);}}
